class K:  # counts evaluations of a[i] == key
    n = 0
    def __init__(s, v): s.v = v
    def __eq__(s, o): K.n += 1; return s.v == o.v
def linear_search(a, key):
    for i in range(len(a)):
        if a[i] == key:
            return i
    return -1
raw = [4, 8, 4, 1, 6, 8, 4, 2, 9, 6]; a = [K(x) for x in raw]; tot = 0
for v in sorted(set(raw)):
    K.n = 0; linear_search(a, K(v)); tot += K.n
print(tot / len(set(raw)))  # 4.8333...

